import fitz, sys
p = r'G:\My Drive\Athletic Performance & Sports Science\Shared Reference Library\From Landon Evans\Training Books\Transfer of Trainng in Sports - Bondarchuk.pdf'
doc = fitz.open(p)
pages = sys.argv[1:]
for spec in pages:
    if '-' in spec:
        a, b = spec.split('-')
        rng = range(int(a), int(b) + 1)
    else:
        rng = [int(spec)]
    for n in rng:
        print(f"\n===== PDF page {n} (viewer {n+1}) =====")
        print(doc[n].get_text())

